import FreeCAD as App
import Part

doc = App.newDocument("HostelCluster")

building_length = 30000
building_width = 20000
floor_height = 3000
num_floors = 30
building_spacing = 5000
num_buildings = 4

def create_building_foundation(x_offset):
    foundation = Part.makeBox(building_length + 2000, building_width + 2000, 1500)
    foundation.translate(App.Vector(x_offset - 1000, -1000, -1500))
    return foundation

def create_structural_columns(x_offset):
    columns = []
    column_spacing_x = 6000
    column_spacing_y = 5000
    column_size = 400

    for floor in range(num_floors + 1):
        z_pos = floor * floor_height
        for i in range(6):
            x_pos = x_offset + i * column_spacing_x
            for j in range(5):
                y_pos = j * column_spacing_y
                column = Part.makeBox(column_size, column_size, floor_height)
                column.translate(App.Vector(x_pos - column_size/2, y_pos - column_size/2, z_pos))
                columns.append(column)

    return columns

def create_floor_slabs(x_offset):
    slabs = []
    for floor in range(num_floors):
        z_pos = floor * floor_height
        slab = Part.makeBox(building_length, building_width, 300)
        slab.translate(App.Vector(x_offset, 0, z_pos))
        slabs.append(slab)
    return slabs

def create_structural_steel_connections(x_offset):
    connections = []
    connection_size = 200

    for floor in range(num_floors):
        z_pos = floor * floor_height + floor_height - 100
        for i in range(5):
            x_pos = x_offset + i * 6000
            for j in range(4):
                y_pos = j * 5000
                connection = Part.makeBox(connection_size, connection_size, 200)
                connection.translate(App.Vector(x_pos - connection_size/2, y_pos - connection_size/2, z_pos))
                connections.append(connection)

    return connections

def create_facade_panels(x_offset):
    panels = []
    panel_width = 1500
    glass_width = 50
    concrete_width = 200

    for floor in range(num_floors):
        z_pos = floor * floor_height + 300
        for i in range(20):
            x_pos = x_offset + i * panel_width
            if i % 2 == 0:
                panel = Part.makeBox(concrete_width, building_width, floor_height - 600)
                panel.translate(App.Vector(x_pos, 0, z_pos))
            else:
                panel = Part.makeBox(glass_width, building_width, floor_height - 600)
                panel.translate(App.Vector(x_pos, 0, z_pos))
            panels.append(panel)

    return panels

def create_vertical_mullions(x_offset):
    mullions = []
    mullion_width = 100
    mullion_depth = 100

    for floor in range(num_floors):
        z_pos = floor * floor_height + 300
        for i in range(21):
            x_pos = x_offset + i * 1500
            mullion = Part.makeBox(mullion_width, building_width + mullion_depth*2, floor_height - 600)
            mullion.translate(App.Vector(x_pos - mullion_width/2, -mullion_depth, z_pos))
            mullions.append(mullion)

    return mullions

def create_balcony_windows(x_offset):
    balconies = []
    balcony_width = 1200
    balcony_height = 1500
    balcony_depth = 600
    railing_height = 1100

    balcony_floors = [5, 10, 15, 20, 25, 30]

    for floor in balcony_floors:
        z_pos = (floor - 1) * floor_height + 900
        for i in range(20):
            x_pos = x_offset + i * 1500 + 150
            if i % 2 == 0:
                balcony = Part.makeBox(balcony_width, balcony_depth, balcony_height)
                balcony.translate(App.Vector(x_pos, building_width, z_pos))
                balconies.append(balcony)

                railing = Part.makeBox(balcony_width, 50, railing_height)
                railing.translate(App.Vector(x_pos, building_width + balcony_depth - 25, z_pos + balcony_height - railing_height))
                balconies.append(railing)

    return balconies

def create_hostel_rooms(x_offset):
    rooms = []
    room_length = 6000
    room_width = 5000

    for floor in range(1, num_floors):
        z_pos = floor * floor_height + 300
        for i in range(5):
            for j in range(4):
                x_pos = x_offset + j * 6000 + 500
                y_pos = i * 4000
                room = Part.makeBox(room_length, room_width, floor_height - 600)
                room.translate(App.Vector(x_pos, y_pos, z_pos))
                rooms.append(room)

    return rooms

def create_corridors(x_offset):
    corridors = []
    corridor_width = 2000

    for floor in range(1, num_floors):
        z_pos = floor * floor_height + 300
        corridor = Part.makeBox(building_length - 2000, corridor_width, floor_height - 600)
        corridor.translate(App.Vector(x_offset + 1000, building_width/2 - corridor_width/2, z_pos))
        corridors.append(corridor)

    return corridors

def create_double_height_lobby(x_offset):
    lobby = Part.makeBox(building_length - 4000, building_width - 4000, floor_height * 2)
    lobby.translate(App.Vector(x_offset + 2000, 2000, 0))
    return lobby

def create_elevator_core(x_offset):
    cores = []
    core_size = 4000

    elevator_core = Part.makeBox(core_size, core_size, num_floors * floor_height)
    elevator_core.translate(App.Vector(x_offset + building_length - core_size - 1000, building_width/2 - core_size/2, 0))
    cores.append(elevator_core)

    stair_core = Part.makeBox(core_size, core_size, num_floors * floor_height)
    stair_core.translate(App.Vector(x_offset + 1000, building_width/2 - core_size/2, 0))
    cores.append(stair_core)

    return cores

def create_horizontal_banding(x_offset):
    bands = []
    band_height = 100

    for floor in range(num_floors):
        z_pos = floor * floor_height + floor_height - band_height
        band = Part.makeBox(building_length, building_width, band_height)
        band.translate(App.Vector(x_offset, 0, z_pos))
        bands.append(band)

    return bands

building_objects = []

for i in range(num_buildings):
    x_offset = i * (building_length + building_spacing)

    try:
        foundation = create_building_foundation(x_offset)
        found_obj = doc.addObject("Part::Feature", f"Foundation_Building_{i+1}")
        found_obj.Shape = foundation
        if hasattr(found_obj, 'ViewObject'):
            found_obj.ViewObject.ShapeColor = (0.5, 0.5, 0.5)
        building_objects.append(found_obj)
    except Exception as e:
        print(f"Error creating foundation for building {i+1}: {e}")

    try:
        columns = create_structural_columns(x_offset)
        for j, column in enumerate(columns):
            col_obj = doc.addObject("Part::Feature", f"Column_{i+1}_{j+1}")
            col_obj.Shape = column
            if hasattr(col_obj, 'ViewObject'):
                col_obj.ViewObject.ShapeColor = (0.7, 0.7, 0.7)
            building_objects.append(col_obj)
    except Exception as e:
        print(f"Error creating columns for building {i+1}: {e}")

    try:
        steel_connections = create_structural_steel_connections(x_offset)
        for j, connection in enumerate(steel_connections):
            steel_obj = doc.addObject("Part::Feature", f"SteelConnection_{i+1}_{j+1}")
            steel_obj.Shape = connection
            if hasattr(steel_obj, 'ViewObject'):
                steel_obj.ViewObject.ShapeColor = (0.4, 0.4, 0.4)
            building_objects.append(steel_obj)
    except Exception as e:
        print(f"Error creating steel connections for building {i+1}: {e}")

    try:
        slabs = create_floor_slabs(x_offset)
        for j, slab in enumerate(slabs):
            slab_obj = doc.addObject("Part::Feature", f"Slab_{i+1}_{j+1}")
            slab_obj.Shape = slab
            if hasattr(slab_obj, 'ViewObject'):
                slab_obj.ViewObject.ShapeColor = (0.8, 0.8, 0.8)
            building_objects.append(slab_obj)
    except Exception as e:
        print(f"Error creating slabs for building {i+1}: {e}")

    try:
        facade_panels = create_facade_panels(x_offset)
        for j, panel in enumerate(facade_panels):
            panel_obj = doc.addObject("Part::Feature", f"FacadePanel_{i+1}_{j+1}")
            panel_obj.Shape = panel
            if hasattr(panel_obj, 'ViewObject'):
                if j % 2 == 0:
                    panel_obj.ViewObject.ShapeColor = (0.6, 0.6, 0.6)
                else:
                    panel_obj.ViewObject.ShapeColor = (0.8, 0.9, 1.0)
                    panel_obj.ViewObject.Transparency = 50
            building_objects.append(panel_obj)
    except Exception as e:
        print(f"Error creating facade panels for building {i+1}: {e}")

    try:
        mullions = create_vertical_mullions(x_offset)
        for j, mullion in enumerate(mullions):
            mullion_obj = doc.addObject("Part::Feature", f"Mullion_{i+1}_{j+1}")
            mullion_obj.Shape = mullion
            if hasattr(mullion_obj, 'ViewObject'):
                mullion_obj.ViewObject.ShapeColor = (0.3, 0.3, 0.3)
            building_objects.append(mullion_obj)
    except Exception as e:
        print(f"Error creating mullions for building {i+1}: {e}")

    try:
        balconies = create_balcony_windows(x_offset)
        for j, balcony in enumerate(balconies):
            balcony_obj = doc.addObject("Part::Feature", f"Balcony_{i+1}_{j+1}")
            balcony_obj.Shape = balcony
            if hasattr(balcony_obj, 'ViewObject'):
                balcony_obj.ViewObject.ShapeColor = (0.9, 0.9, 0.9)
                balcony_obj.ViewObject.Transparency = 30
            building_objects.append(balcony_obj)
    except Exception as e:
        print(f"Error creating balconies for building {i+1}: {e}")

    try:
        rooms = create_hostel_rooms(x_offset)
        for j, room in enumerate(rooms):
            room_obj = doc.addObject("Part::Feature", f"Room_{i+1}_{j+1}")
            room_obj.Shape = room
            if hasattr(room_obj, 'ViewObject'):
                room_obj.ViewObject.ShapeColor = (0.95, 0.95, 0.95)
                room_obj.ViewObject.Transparency = 70
            building_objects.append(room_obj)
    except Exception as e:
        print(f"Error creating rooms for building {i+1}: {e}")

    try:
        corridors = create_corridors(x_offset)
        for j, corridor in enumerate(corridors):
            corr_obj = doc.addObject("Part::Feature", f"Corridor_{i+1}_{j+1}")
            corr_obj.Shape = corridor
            if hasattr(corr_obj, 'ViewObject'):
                corr_obj.ViewObject.ShapeColor = (0.9, 0.9, 0.9)
            building_objects.append(corr_obj)
    except Exception as e:
        print(f"Error creating corridors for building {i+1}: {e}")

    try:
        lobby = create_double_height_lobby(x_offset)
        lobby_obj = doc.addObject("Part::Feature", f"Lobby_{i+1}")
        lobby_obj.Shape = lobby
        if hasattr(lobby_obj, 'ViewObject'):
            lobby_obj.ViewObject.ShapeColor = (0.8, 0.8, 0.9)
        building_objects.append(lobby_obj)
    except Exception as e:
        print(f"Error creating lobby for building {i+1}: {e}")

    try:
        elevator_cores = create_elevator_core(x_offset)
        for j, core in enumerate(elevator_cores):
            core_obj = doc.addObject("Part::Feature", f"Core_{i+1}_{j+1}")
            core_obj.Shape = core
            if hasattr(core_obj, 'ViewObject'):
                core_obj.ViewObject.ShapeColor = (0.6, 0.6, 0.6)
            building_objects.append(core_obj)
    except Exception as e:
        print(f"Error creating elevator cores for building {i+1}: {e}")

    try:
        bands = create_horizontal_banding(x_offset)
        for j, band in enumerate(bands):
            band_obj = doc.addObject("Part::Feature", f"Banding_{i+1}_{j+1}")
            band_obj.Shape = band
            if hasattr(band_obj, 'ViewObject'):
                band_obj.ViewObject.ShapeColor = (0.7, 0.7, 0.7)
            building_objects.append(band_obj)
    except Exception as e:
        print(f"Error creating horizontal banding for building {i+1}: {e}")

buildings_group = doc.addObject("App::DocumentObjectGroup", "HostelBuildings")
buildings_group.Group = building_objects

doc.recompute()
